package universe

import "github.com/ditto-assistant/dittobench-datagen/persona"

// StoryV13QuestionSurfaces exposes the story v2 question grammars to the
// generator-inverse probe (cmd/parserprobe) so its frame banks are the
// generator's own rather than a hand copy that drifts. The anchor grammar's
// root is "anchor" and binds the {nick} and {alias} slots; each task grammar's
// root is "task". Keys are the artifact QuestionType ("world-" + oracle kind).
// A story v2 question is storySentence(anchor) + " " + task. Exporting the
// banks changes no generated bytes.
func StoryV13QuestionSurfaces() (anchor persona.Grammar, tasks map[string]persona.Grammar) {
	anchor = persona.Grammar{}
	for symbol, alts := range storyV13AnchorGrammar {
		anchor[symbol] = append([]string(nil), alts...)
	}
	tasks = make(map[string]persona.Grammar, len(storyV13TaskGrammars))
	for kind, grammar := range storyV13TaskGrammars {
		copied := persona.Grammar{}
		for symbol, alts := range grammar {
			copied[symbol] = append([]string(nil), alts...)
		}
		tasks["world-"+kind] = copied
	}
	return anchor, tasks
}
